/** Preregistered bounded frozen-rule finite subgame, fresh-history diagnostics only. */
import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {performance} from 'node:perf_hooks';import assert from 'node:assert/strict';import * as f from '../search-performance-v5/baseline-rules.js';
const manifestPath='output/local-experiments/js-directdrop-r1-fairy-screen-2026-10-28/manifest.json',rules=JSON.parse(await readFile(manifestPath)).rules;const planPath='research/competitive-engine-v1/three-piece-retrograde-plan-2026-10-28.md';const start=performance.now(),states=[],excluded=[],map=new Map(),caps={states:20000,edges:200000,millis:10000};let attempted=0,edges=0,complete=false,failure=null;const stop=Symbol();function check(){if(performance.now()-start>=caps.millis)throw stop;}
try{
for(let w=0;w<16;w++)for(let b=0;b<16;b++){if(w===b)continue;for(const owner of ['white','black'])for(let loc=0;loc<=16;loc++){if(loc===w||loc===b)continue;for(const turn of ['white','black']){check();attempted++;const descriptor={w,b,owner,loc,turn};if(Math.max(Math.abs((w%4)-(b%4)),Math.abs((w>>2)-(b>>2)))<=1){excluded.push({...descriptor,reason:'adjacent-kings'});continue;}const p=f.createInitialPosition(rules);p.phase='play';p.turn=turn;p.board.fill(null);p.board[w]={owner:'white',piece:'king'};p.board[b]={owner:'black',piece:'king'};p.banks={white:[],black:[]};if(loc===16)p.banks[owner]=['rook'];else p.board[loc]={owner,piece:'rook'};if(f.isInCheck(p,turn==='white'?'black':'white')){excluded.push({...descriptor,reason:'previous-side-in-check'});continue;}const key=f.positionKey(p);p.repetitions={[key]:1};assert(!map.has(key));if(states.length>=caps.states)throw stop;map.set(key,states.length);states.push({descriptor,key,position:p,result:null,edges:[]});}}}
for(let i=0;i<states.length;i++){check();const s=states[i],before=JSON.stringify(s.position),actions=f.legalActions(s.position);s.result=f.getResult(s.position);if(!s.result)for(const action of actions){check();if(edges>=caps.edges)throw stop;const next=f.applyLegalAction(s.position,action),key=f.positionKey(next),to=map.get(key);edges++;if(to===undefined){failure={reason:'closure',from:i,action,next};throw stop;}s.edges.push({action,to});}assert.equal(JSON.stringify(s.position),before);}
complete=true;
}catch(e){if(e!==stop)throw e;failure??={reason:'cap',elapsed:performance.now()-start,attempted,states:states.length,edges};}
const constructionMillis=performance.now()-start;let certificates=null;
if(complete){const win=states.map(s=>s.result?.type==='win'?s.result.winner:null),rank=states.map(s=>s.result?.type==='win'?0:null);let changed=true,passes=0;while(changed){changed=false;passes++;for(let i=0;i<states.length;i++){const s=states[i];if(win[i]||s.result)continue;const who=s.position.turn,enemy=who==='white'?'black':'white',own=s.edges.filter(e=>win[e.to]===who);if(own.length){win[i]=who;rank[i]=1+Math.min(...own.map(e=>rank[e.to]));changed=true;}else if(s.edges.length&&s.edges.every(e=>win[e.to]===enemy)){win[i]=enemy;rank[i]=1+Math.max(...s.edges.map(e=>rank[e.to]));changed=true;}}}
const strategy=states.map((s,i)=>{if(s.result)return null;if(win[i]===s.position.turn)return s.edges.find(e=>win[e.to]===win[i]&&rank[e.to]<rank[i]);if(win[i])return null;return s.edges.find(e=>!win[e.to]);});let verified=0;for(let i=0;i<states.length;i++){const s=states[i];if(s.result){assert.equal(win[i],s.result.winner??null);verified++;continue;}assert(s.edges.length);if(win[i]===s.position.turn){assert(strategy[i]);assert(rank[strategy[i].to]<rank[i]);}else if(win[i])assert(s.edges.every(e=>win[e.to]===win[i]&&rank[e.to]<rank[i]));else{assert(strategy[i]);assert(s.edges.every(e=>win[e.to]!==s.position.turn));assert(!win[strategy[i].to]);}verified++;}
certificates={winner:win,rank,strategy,passes,verified,drawProof:'For each residual nonterminal, a stored successor remains residual or terminal draw; all exits to opponent-win states can be avoided. Against any opponent, an outcome better for that opponent is never forced. Finite residual play either reaches stalemate or repeats a position three times. Winning rank decreases on chosen winner moves and all loser responses, precluding repeats from current-key-once fresh history. Earlier repetition counts excluded.'};}
const hashes={};for(const p of [manifestPath,planPath,'research/search-performance-v5/baseline-rules.js','research/search-performance-v5/baseline-board-masks.js'])hashes[p]=createHash('sha256').update(await readFile(p)).digest('hex');const summary={attempted,excluded:excluded.length,states:states.length,edges,complete,failure,constructionMillis,terminalWins:states.filter(s=>s.result?.type==='win').length,terminalDraws:states.filter(s=>s.result?.type==='draw').length,whiteWins:certificates?.winner.filter(x=>x==='white').length,blackWins:certificates?.winner.filter(x=>x==='black').length,draws:certificates?.winner.filter(x=>x===null).length,verified:certificates?.verified};await writeFile('research/competitive-engine-v1/three-piece-retrograde.json',JSON.stringify({purpose:'Preregistered complete finite-subgame graph diagnostic; fresh current-key-once history only. No production cache/search/game comparison. No arbitrary-history or strength claim. All exclusions/partial attempts retained.',caps,rules,hashes,script:await readFile(new URL(import.meta.url),'utf8'),summary,excluded,states,certificates},null,2)+'\n');console.log(JSON.stringify(summary));
